// RADIO-B1 — the rules Calvary Radio stands on (docs/RADIO-CONTRACT.md §2, §3, §5, §9).
//
//   npm run test:rules   (emulator)
//
// Every rule here is generated by scripts/radio/write-rules.mjs from app/lib/radio/schema.js.
// Times are relative to the emulator's own clock (`now` in the rules is the server's).
import { test, before, after, beforeEach, describe } from 'node:test';
import assert from 'node:assert/strict';
import { serverTimestamp } from 'firebase/database';
import { makeEnv, seed, assertFails, assertSucceeds, OWNER, STRANGER, OTHER, FOUNDER_A } from './helpers.mjs';
import { LIVE_GRACE_MS, HEARTS_MAX } from '../../app/lib/radio/schema.js';

let env, owner, stranger, writer, founder, anon;
before(async () => {
  env = await makeEnv();
  owner = env.authenticatedContext(OWNER).database();
  stranger = env.authenticatedContext(STRANGER).database();
  writer = env.authenticatedContext(OTHER).database();
  founder = env.authenticatedContext(FOUNDER_A).database();
  anon = env.unauthenticatedContext().database();
});
after(async () => { await env?.cleanup(); });
beforeEach(async () => { await env.clearDatabase(); });

const H = 3600000;
const now = () => Date.now();
const story = (o = {}) => ({ releaseAtMs: now() - H, durationMs: 20 * 60000, readAlong: '/stories/tale', status: 'scheduled', updatedAt: 1, ...o });
const instalment = (o = {}) => {
  const premiereAtMs = o.premiereAtMs ?? now() - 60000;
  const durationMs = o.durationMs ?? 50 * 60000;
  return { premiereAtMs, durationMs, releaseAtMs: premiereAtMs + durationMs, readAlong: '/series/instalment/bp-i1', status: 'scheduled', updatedAt: 1, ...o };
};
const collection = (o = {}) => ({
  number: 1, releaseAtMs: now() - H, status: 'scheduled', updatedAt: 1,
  running: { o1: { kind: 'story', id: 'tale' }, o2: { kind: 'instalment', id: 'bp-i1' } }, ...o,
});

describe('radio_collections/c{n}', () => {
  test('anyone reads a scheduled collection from its release; not before, not a draft', async () => {
    await seed(env, {
      'radio_collections/c1': collection(),
      'radio_collections/c2': collection({ number: 2, releaseAtMs: now() + H }),
      'radio_collections/c3': collection({ number: 3, status: 'draft' }),
    });
    await assertSucceeds(anon.ref('radio_collections/c1').get());
    await assertSucceeds(owner.ref('radio_collections/c1').get());
    await assertFails(owner.ref('radio_collections/c2').get());
    await assertFails(owner.ref('radio_collections/c3').get());
    await assertFails(owner.ref('radio_collections').get());
    await assertSucceeds(founder.ref('radio_collections/c2').get());
    await assertSucceeds(founder.ref('radio_collections/c3').get());
  });
  test('only founders write, and only the shape', async () => {
    await assertFails(owner.ref('radio_collections/c1').set(collection()));
    await assertSucceeds(founder.ref('radio_collections/c1').set(collection()));
    await assertFails(founder.ref('radio_collections/1').set(collection()));
    await assertFails(founder.ref('radio_collections/c4').set(collection({ number: 4, extra: true })));
    await assertFails(founder.ref('radio_collections/c4').set(collection({ number: 4, status: 'live' })));
    await assertFails(founder.ref('radio_collections/c4').set(collection({ number: 4, running: { x1: { kind: 'story', id: 'a' } } })));
    await assertFails(founder.ref('radio_collections/c4').set(collection({ number: 4, running: { o1: { kind: 'poem', id: 'a' } } })));
    await assertFails(founder.ref('radio_collections/c4').set(collection({ number: 4, running: { o1: { kind: 'story', id: 'a/b' } } })));
  });
});

describe('radio_audio/{stories|instalments}/{id}', () => {
  test('a story reads from its release; a scheduled one before then only to founders and its writer', async () => {
    await seed(env, {
      'cms_stories/tale': { authorUid: OTHER, published: true },
      'cms_stories/later': { authorUid: OTHER, published: true },
      'radio_audio/stories/tale': story(),
      'radio_audio/stories/later': story({ releaseAtMs: now() + H, readAlong: '/stories/later' }),
    });
    await assertSucceeds(anon.ref('radio_audio/stories/tale').get());
    await assertFails(owner.ref('radio_audio/stories/later').get());
    await assertSucceeds(writer.ref('radio_audio/stories/later').get());
    await assertSucceeds(founder.ref('radio_audio/stories/later').get());
    await assertFails(owner.ref('radio_audio/stories').get());
  });
  test('an instalment reads from its premiere, before its on-demand release; not before the premiere', async () => {
    await seed(env, {
      'series_instalments_detail/bp-i1': { authorUid: OTHER },
      'radio_audio/instalments/bp-i1': instalment(),
      'radio_audio/instalments/bp-i2': instalment({ premiereAtMs: now() + 7 * 24 * H, readAlong: '/series/instalment/bp-i2' }),
    });
    await assertSucceeds(owner.ref('radio_audio/instalments/bp-i1').get());
    await assertFails(owner.ref('radio_audio/instalments/bp-i2').get());
    await assertSucceeds(founder.ref('radio_audio/instalments/bp-i2').get());
  });
  test('draft and withdrawn records stay hidden whatever their times say', async () => {
    await seed(env, {
      'radio_audio/stories/tale': story({ status: 'withdrawn' }),
      'radio_audio/instalments/bp-i1': instalment({ status: 'draft' }),
    });
    await assertFails(owner.ref('radio_audio/stories/tale').get());
    await assertFails(owner.ref('radio_audio/instalments/bp-i1').get());
  });
  test('only founders write; the premiere must finish before on-demand release; the shape is closed', async () => {
    await assertFails(owner.ref('radio_audio/stories/tale').set(story()));
    await assertSucceeds(founder.ref('radio_audio/stories/tale').set(story({ narrator: { name: 'A narrator' }, engineer: { name: 'An engineer' }, version: 'g1', collection: 'c1' })));
    await assertSucceeds(founder.ref('radio_audio/instalments/bp-i1').set(instalment({ access: { freeForGold: true, openToFree: true } })));
    await assertFails(founder.ref('radio_audio/instalments/bp-i1').set(instalment({ releaseAtMs: now() })));
    await assertFails(founder.ref('radio_audio/instalments/bp-i1').set(instalment({ access: { openToFree: true, freeForGold: false } })));
    await assertFails(founder.ref('radio_audio/stories/tale').set(story({ access: { freeForGold: true } })));
    await assertFails(founder.ref('radio_audio/stories/tale').set(story({ readAlong: '/stories/another' })));
    await assertFails(founder.ref('radio_audio/stories/tale').set(story({ path: 'radio/tale.mp3' })));
    await assertFails(founder.ref('radio_audio/stories/tale').set(story({ durationMs: 0 })));
    await assertFails(founder.ref('radio_audio/podcasts/tale').set(story()));
  });
});

describe('radio_live/{kind}/{id}: the room, keyed by premiere', () => {
  const ROOM = 'radio_live/instalments/bp-i1';
  test('a listener joins and leaves only their own presence, and only while the room is open', async () => {
    await seed(env, { 'radio_audio/instalments/bp-i1': instalment() });
    await assertSucceeds(owner.ref(`${ROOM}/listeners/${OWNER}`).set(true));
    await assertFails(owner.ref(`${ROOM}/listeners/${STRANGER}`).set(true));
    await assertFails(owner.ref(`${ROOM}/listeners/${OWNER}`).set(5));
    await assertFails(anon.ref(`${ROOM}/listeners/${OWNER}`).set(true));
    await assertSucceeds(owner.ref(`${ROOM}/listeners/${OWNER}`).remove());
  });
  test('before the premiere, after it (plus the grace) and for a draft, nobody joins; leaving still works', async () => {
    await seed(env, {
      'radio_audio/instalments/early': instalment({ premiereAtMs: now() + H, readAlong: '/series/instalment/early' }),
      'radio_audio/instalments/done': instalment({ premiereAtMs: now() - 2 * H, durationMs: 50 * 60000, readAlong: '/series/instalment/done' }),
      'radio_audio/instalments/drafted': instalment({ status: 'draft', readAlong: '/series/instalment/drafted' }),
      'radio_audio/stories/tale': story(),
      [`radio_live/instalments/done/listeners/${OWNER}`]: true,
    });
    await assertFails(owner.ref(`radio_live/instalments/early/listeners/${OWNER}`).set(true));
    await assertFails(owner.ref(`radio_live/instalments/done/listeners/${OWNER}`).set(true));
    await assertFails(owner.ref(`radio_live/instalments/drafted/listeners/${OWNER}`).set(true));
    await assertFails(owner.ref(`radio_live/stories/tale/listeners/${OWNER}`).set(true)); // no premiere, no room
    await assertFails(owner.ref(`radio_live/instalments/none/listeners/${OWNER}`).set(true));
    await assertSucceeds(owner.ref(`radio_live/instalments/done/listeners/${OWNER}`).remove());
  });
  test('the grace: the room stays open for the late minutes after the audio ends', async () => {
    const durationMs = 30 * 60000;
    await seed(env, { 'radio_audio/instalments/bp-i1': instalment({ premiereAtMs: now() - durationMs - LIVE_GRACE_MS / 2, durationMs }) });
    await assertSucceeds(owner.ref(`${ROOM}/listeners/${OWNER}`).set(true));
  });
  test('nobody reads anyone else\'s presence or hearts, or the whole room: only their own, and the counts', async () => {
    await seed(env, {
      'radio_audio/instalments/bp-i1': instalment(),
      [`${ROOM}/listeners/${STRANGER}`]: true,
      [`${ROOM}/hearts/${STRANGER}`]: { n: 3, at: 1 },
      [`${ROOM}/counts`]: { listeners: 1, hearts: 3, at: 1 },
    });
    await assertFails(owner.ref(`${ROOM}/listeners`).get());
    await assertFails(owner.ref(`${ROOM}/hearts`).get());
    await assertFails(owner.ref(ROOM).get());
    await assertFails(owner.ref(`${ROOM}/listeners/${STRANGER}`).get());
    await assertSucceeds(stranger.ref(`${ROOM}/listeners/${STRANGER}`).get());
    await assertSucceeds(stranger.ref(`${ROOM}/hearts/${STRANGER}`).get());
    const counts = await assertSucceeds(owner.ref(`${ROOM}/counts`).get());
    assert.deepEqual(counts.val(), { listeners: 1, hearts: 3, at: 1 });
    await assertFails(anon.ref(`${ROOM}/counts`).get());
  });
  test('no client writes the counts, founders included: the server job does', async () => {
    await seed(env, { 'radio_audio/instalments/bp-i1': instalment() });
    await assertFails(owner.ref(`${ROOM}/counts`).set({ listeners: 9999, hearts: 9999, at: now() }));
    await assertFails(founder.ref(`${ROOM}/counts`).set({ listeners: 1, hearts: 1, at: now() }));
    await assertFails(owner.ref(`${ROOM}/extra`).set(true));
  });
  test('hearts: one more each time, stamped by the server, at most one a second, only while open', async () => {
    await seed(env, { 'radio_audio/instalments/bp-i1': instalment() });
    const ref = owner.ref(`${ROOM}/hearts/${OWNER}`);
    await assertFails(ref.set({ n: 5, at: serverTimestamp() }));          // must start at 1
    await assertFails(ref.set({ n: 1, at: now() - 5000 }));               // must be the server's time
    await assertSucceeds(ref.set({ n: 1, at: serverTimestamp() }));
    await assertFails(ref.set({ n: 2, at: serverTimestamp() }));          // inside the second
    await assertFails(ref.set({ n: 3, at: serverTimestamp() }));          // never skips
    await assertFails(ref.remove());                                      // a client never resets it
    await assertFails(owner.ref(`${ROOM}/hearts/${STRANGER}`).set({ n: 1, at: serverTimestamp() }));
  });
  test('hearts: the next one lands after a second, and the cap holds', async () => {
    await seed(env, {
      'radio_audio/instalments/bp-i1': instalment(),
      [`${ROOM}/hearts/${OWNER}`]: { n: 1, at: now() - 2000 },
      [`${ROOM}/hearts/${STRANGER}`]: { n: HEARTS_MAX, at: now() - 2000 },
    });
    await assertSucceeds(owner.ref(`${ROOM}/hearts/${OWNER}`).set({ n: 2, at: serverTimestamp() }));
    await assertFails(stranger.ref(`${ROOM}/hearts/${STRANGER}`).set({ n: HEARTS_MAX + 1, at: serverTimestamp() }));
  });
  test('hearts after the room closes are refused', async () => {
    await seed(env, {
      'radio_audio/instalments/bp-i1': instalment({ premiereAtMs: now() - 3 * H }),
      [`${ROOM}/hearts/${OWNER}`]: { n: 1, at: now() - 2 * H },
    });
    await assertFails(owner.ref(`${ROOM}/hearts/${OWNER}`).set({ n: 2, at: serverTimestamp() }));
  });
});

describe('listening_position/{uid}/{kind}/{id}', () => {
  const pos = (o = {}) => ({ positionMs: 60000, durationMs: 1200000, version: 'g1', updatedAt: serverTimestamp(), ...o });
  test('the listener reads and writes their own, and nobody else\'s', async () => {
    await assertSucceeds(owner.ref(`listening_position/${OWNER}/stories/tale`).set(pos()));
    await assertSucceeds(owner.ref(`listening_position/${OWNER}/instalments/bp-i1`).set(pos()));
    await assertSucceeds(owner.ref(`listening_position/${OWNER}`).get());
    await assertFails(stranger.ref(`listening_position/${OWNER}`).get());
    await assertFails(stranger.ref(`listening_position/${OWNER}/stories/tale`).set(pos()));
    await assertFails(founder.ref(`listening_position/${OWNER}`).get());
    await assertSucceeds(owner.ref(`listening_position/${OWNER}/stories/tale`).remove());
  });
  test('the shape: inside the file, a version, the server\'s time, nothing else', async () => {
    const ref = owner.ref(`listening_position/${OWNER}/stories/tale`);
    await assertFails(ref.set(pos({ positionMs: 2000000 })));
    await assertFails(ref.set(pos({ positionMs: -1 })));
    await assertFails(ref.set(pos({ version: '' })));
    await assertFails(ref.set(pos({ updatedAt: now() - 60000 })));
    await assertFails(ref.set(pos({ extra: 1 })));
    await assertFails(owner.ref(`listening_position/${OWNER}/podcasts/tale`).set(pos()));
    await assertFails(owner.ref(`listening_position/${OWNER}/stories/a b`).set(pos()));
  });
});
